var o=[{title:`O que a forma altera`,text:`Em alguns levantamentos o peso suspenso pode mover-se à volta do pulso ou do antebraço e equilibra-se de forma diferente de um haltere. Os agachamentos goblet, os levantamentos terra e as caminhadas com carga usam a kettlebell de formas bastante simples. As cargadas, os arranques e outras competências balísticas acrescentam exigências de balanço e coordenação que podem ser demais para iniciantes.`},{title:`Comece pelo básico`,text:`Aprenda uma dobra de anca controlada e um levantamento terra simples antes de tentar um swing, e faça agachamentos goblet, levantamentos terra, remadas ou caminhadas com carga antes do trabalho balístico de grande coordenação. Escolha uma kettlebell leve o suficiente para movimentos repetidos e estáveis, mas pesada o suficiente para o desafiar. O sexo ou a idade, por si só, não lhe dizem o peso inicial certo; contam a sua força, a sua experiência e o exercício que escolhe.`},{title:`Mecânica do swing`,text:`Num swing comum com as duas mãos, a kettlebell desloca-se de entre as pernas até cerca da altura do peito, impulsionada por uma poderosa extensão da anca e não por levantar os braços. Mantenha a coluna controlada, deixe os joelhos dobrarem um pouco e guie a kettlebell pelo mesmo arco de cada vez. Não transforme o exercício num agachamento profundo com uma elevação frontal.`},{title:`Segurança e progressão`,text:`Pratique quando o chão, as suas mãos e a zona à sua volta estiverem livres e secos. Deixe espaço suficiente à frente e atrás de si para a trajetória da kettlebell. Pare quando a pega ou a técnica da dobra de anca começar a ceder. Passe dos levantamentos terra e das dobras de anca controladas para séries curtas de swings só quando conseguir fazer o movimento de forma fiável.`},{title:`Usar o TrainUp`,text:`Defina com rigor, no Perfil, o tamanho do espaço no chão, a altura do teto e a superfície. O seu plano escolhe apenas exercícios que se adaptam ao seu espaço, superfície, limitações e coordenação, o que é importante para movimentos de balanço numa sala pequena.`}];var s=[{label:`ACE: técnica do swing de kettlebell com as duas mãos`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var t={sections:o,sources:s};export{t as default,o as sections,s as sources};